// O frontend envia Content-Type: text/plain (evita preflight CORS),
// por isso o corpo pode chegar como string em vez de objeto já parseado.
let body = msg.payload;

if (typeof body === "string") {
    try {
        body = JSON.parse(body);
    } catch (error) {
        msg.statusCode = 400;
        msg.payload = { success: false, error: "Payload inválido (JSON malformado)" };
        return [null, msg];
    }
}

body = body || {};

// Ligar/desligar - comando simples, sem mais validações
if (typeof body.on === "boolean") {
    msg.payload = { on: body.on };
    return [msg, null];
}

const validModes = ["cool", "fan", "dry"];
const validFans = ["auto", "low", "medium", "high", "turbo"];

if (body.mode !== undefined && !validModes.includes(body.mode)) {
    msg.statusCode = 400;
    msg.payload = { success: false, error: "Modo inválido" };
    return [null, msg];
}

if (body.fan !== undefined && !validFans.includes(body.fan)) {
    msg.statusCode = 400;
    msg.payload = { success: false, error: "Velocidade da ventoinha inválida" };
    return [null, msg];
}

if (body.temp !== undefined) {
    const temp = Number(body.temp);
    if (!Number.isInteger(temp) || temp < 16 || temp > 30) {
        msg.statusCode = 400;
        msg.payload = { success: false, error: "Temperatura inválida" };
        return [null, msg];
    }
    body.temp = temp;
}

msg.payload = body;
return [msg, null];

const body = msg.payload;

// Ligar/desligar
if (typeof body.on === "boolean") {
    msg.command = body.on ? "on" : "off";
    msg.payload = msg.command;
    return msg;
}

const mode = body.mode;
const fan = body.fan || "auto";
let command;

if (mode === "fan") {
    // Ventilar: o hardware não usa temperatura neste modo - ignorada de propósito
    command = `fan_${fan}`;
} else if (mode === "dry") {
    // Desumidificar: regra isolada, fácil de alterar mais tarde
    command = `dry_${body.temp}_auto`;
} else {
    // "cool" - todas as velocidades são suportadas
    command = `cool_${body.temp}_${fan}`;
}

msg.command = command;
msg.payload = command;
return msg;

let result;

try {
    result = JSON.parse(msg.payload);
} catch (error) {
    msg.statusCode = 200;
    msg.payload = { success: false, error: "Resposta inválida do script Python" };
    return msg;
}

// Encaminha tal como o Python devolveu (success:true/false, error, etc.)
// - o código IR pode ainda não existir em ir_codes.json, e isso não deve
// quebrar a aplicação: o frontend mantém o estado anterior.
msg.statusCode = 200;
msg.payload = result;
return msg;
